/*
 * A110266  Number of blocks of ON cells in n-th row of triangle generated by
 *          Wolfram's "Rule 30".
 * https://oeis.org/A110266
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = number of contiguous blocks of ON cells in the n‑th row
 *            of the triangle generated by Wolfram's Rule 30. The function
 *            simulates Rule 30 up to row n and counts the blocks
 * Range:     u8 n <= 466, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>

seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* offset begins at 1, but guard anyway */

    /* Width of a row never exceeds 2*n-1.  Allocate a few more bits
       as a safety margin. */
    size_t bits   = 2 * (size_t)n + 5;
    size_t words  = (bits + 63ULL) / 64ULL;

    /* Two bit arrays – current and next row.  Use a C‑style cast to
       satisfy both C and C++ compilation. */
    uint64_t *cur  = (uint64_t *)calloc(words, sizeof(uint64_t));
    uint64_t *next = (uint64_t *)calloc(words, sizeof(uint64_t));
    if (!cur || !next) {
        /* Allocation failed; return 0 as a safe fallback. */
        free(cur);
        free(next);
        return 0;
    }

    /* Place the single ON cell at the centre of the array. */
    size_t center = (size_t)n;              /* leaves n free cells left/right */
    cur[center >> 6] |= 1ULL << (center & 63ULL);

    /* Generate rows 2 … n.  Rule 30: new_cell = left XOR (current OR right). */
    for (size_t row = 2; row <= (size_t)n; ++row) {
        for (size_t i = 0; i < words; ++i) {
            uint64_t cw   = cur[i];
            uint64_t left  = cw << 1;
            if (i > 0) left |= cur[i - 1] >> 63;
            uint64_t right = cw >> 1;
            if (i + 1 < words) right |= cur[i + 1] << 63;
            next[i] = left ^ (cw | right);
        }
        /* Swap pointers for the next iteration. */
        uint64_t *tmp = cur;
        cur = next;
        next = tmp;
    }

    /* Count contiguous blocks of 1s in the final row. */
    seq_t blocks = 0;
    int prev = 0;
    for (size_t i = 0; i < words; ++i) {
        uint64_t w = cur[i];
        for (int b = 0; b < 64; ++b) {
            int curr = w & 1ULL;
            if (curr && !prev) ++blocks;
            prev = curr;
            w >>= 1;
        }
    }

    free(cur);
    free(next);
    return blocks;
}
